310	import matter from 'gray-matter';
311	import { RecursiveCharacterTextSplitter } from '@langchain/textsplitters';
312	
313	export const CHUNK_SIZE = 800;
314	export const CHUNK_OVERLAP = 100;
315	
316	export type MarkdownChunk = {
317	  content: string;
318	  headingPath: string[];
319	  startChar: number;
320	  endChar: number;
321	  startLine: number;
322	  endLine: number;
323	  metadata: Record<string, unknown>;
324	};
325	
326	type Heading = { start: number; level: number; title: string; path: string[] };
327	type HeadingEntry = { level: number; title: string };
328	
329	const lineNumberAt = (source: string, offset: number) =>
330	  source.slice(0, Math.max(0, offset)).split('\n').length;
331	
332	const scanHeadings = (source: string): Heading[] => {
333	  const headings: Heading[] = [];
334	  const hierarchy: HeadingEntry[] = [];
335	  let offset = 0;
336	  let fence: string | undefined;
337	
338	  for (const line of source.match(/[^\n]*(?:\n|$)/g) ?? []) {
339	    const withoutNewline = line.replace(/(?:\r?\n|\r)$/, '');
340	    const fenceMatch = withoutNewline.match(/^\s{0,3}(`{3,}|~{3,})/);
341	    if (fenceMatch) {
342	      const marker = fenceMatch[1][0];
343	      if (!fence) fence = marker;
344	      else if (fence === marker) fence = undefined;
345	    } else if (!fence) {
346	      const headingMatch = withoutNewline.match(/^ {0,3}(#{1,4})\s+(.+?)\s*#*\s*$/);
347	      if (headingMatch) {
348	        const level = headingMatch[1].length;
349	        const title = headingMatch[2].trim();
350	        while (hierarchy.length > 0 && hierarchy[hierarchy.length - 1].level >= level) {
351	          hierarchy.pop();
352	        }
353	        hierarchy.push({ level, title });
354	        headings.push({
355	          start: offset,
356	          level,
357	          title,
358	          path: hierarchy.map((entry) => entry.title),
359	        });
360	      }
361	    }
362	    offset += line.length;
363	  }
364	  return headings;
365	};
366	
367	export const splitMarkdown = async (source: string, documentTitle: string) => {
368	  const parsed = matter(source);
369	  const body = parsed.content;
370	  const bodyOffset = body.length === 0 ? source.length : source.indexOf(body);
371	  if (bodyOffset < 0) throw new Error('Unable to locate Markdown body in source');
372	  if (!body.trim()) throw new Error('Document has no Markdown content');
373	
374	  const headings = scanHeadings(body);
375	  const sections = [
376	    ...(headings[0] ? [{ start: 0, end: headings[0].start, path: [] as string[] }] : []),
377	    ...headings.map((heading, index) => ({
378	      start: heading.start,
379	      end: headings[index + 1]?.start ?? body.length,
380	      path: heading.path,
381	    })),
382	  ].filter((section) => section.end > section.start);
383	  if (!sections.length) sections.push({ start: 0, end: body.length, path: [] });
384	
385	  const splitter = RecursiveCharacterTextSplitter.fromLanguage('markdown', {
386	    chunkSize: CHUNK_SIZE,
387	    chunkOverlap: CHUNK_OVERLAP,
388	    keepSeparator: true,
389	  });
390	  const chunks: MarkdownChunk[] = [];
391	
392	  for (const section of sections) {
393	    const sectionText = body.slice(section.start, section.end);
394	    const pieces = await splitter.splitText(sectionText);
395	    let searchStart = 0;
396	    for (const content of pieces) {
397	      const relativeStart = sectionText.indexOf(content, searchStart);
398	      if (relativeStart < 0) throw new Error('Unable to locate generated chunk in source');
399	      const startChar = bodyOffset + section.start + relativeStart;
400	      const endChar = startChar + content.length;
401	      chunks.push({
402	        content,
403	        headingPath: section.path,
404	        startChar,
405	        endChar,
406	        startLine: lineNumberAt(source, startChar),
407	        endLine: lineNumberAt(source, Math.max(startChar, endChar - 1)),
408	        metadata: {
409	          documentTitle,
410	          headingPath: section.path,
411	          frontmatter: parsed.data,
412	        },
413	      });
414	      searchStart = Math.max(relativeStart + 1, relativeStart + content.length - CHUNK_OVERLAP);
415	    }
416	  }
417	  return { chunks, frontmatter: parsed.data };
418	};
