export type DocumentSummary = {
  id: string;
  fundId: string;
  portcoId: string | null;
  title: string;
  filename: string;
  mimeType: string;
  sourceKind: 'seed' | 'uploaded' | 'generated';
  status: 'queued' | 'processing' | 'ready' | 'failed';
  errorMessage: string | null;
