  updatedAt: Date;
  completedAt: Date | null;
};
export type DocumentDetails = DocumentSummary & {
  metadata: Record<string, unknown>;
  content: string;
};
export type CreateDocumentInput = {
  fundId: string;
  portcoId?: string | null;
